"""Build dependency-free public pages from shared bilingual content."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parent.parent
BASE = 'https://oski3k.github.io/pyk-site/'
STORE = 'https://play.google.com/store/apps/details?id=com.oskarsledz.pyk'
PATHS = {'en': ['index.html', 'privacy-en.html', 'delete-account-en.html'], 'pl': ['index-pl.html', 'privacy.html', 'delete-account.html']}
LABELS = {
'en': {'home':'Home', 'privacy':'Privacy policy', 'delete':'Delete account', 'skip':'Skip to content', 'contact':'Contact', 'language':'Language', 'footer':'Small games. Real connections.', 'back':'Back to Pyk', 'updated':'Last updated: 12 October 2026', 'toc':'On this page', 'support':'Need a hand?', 'email':'Email us', 'rights':'Privacy & account'},
'pl': {'home':'Start', 'privacy':'Polityka prywatności', 'delete':'Usuń konto', 'skip':'Przejdź do treści', 'contact':'Kontakt', 'language':'Język', 'footer':'Małe gry. Prawdziwe znajomości.', 'back':'Wróć do Pyk', 'updated':'Aktualizacja: 12 października 2026', 'toc':'Na tej stronie', 'support':'Potrzebujesz pomocy?', 'email':'Napisz do nas', 'rights':'Prywatność i konto'}
}

def layout(lang, page, title, desc, content):
    t = LABELS[lang]
    paths = PATHS[lang]
    other = 'pl' if lang == 'en' else 'en'
    nav = ''.join(f'<a href="{paths[i]}"'+(' aria-current="page"' if i == page else '')+f'>{t[key]}</a>' for i, key in enumerate(['home','privacy','delete']))
    return f'''<!doctype html>
<html lang="{lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(desc)}">
<meta name="theme-color" content="#FFF1D0">
<meta name="referrer" content="strict-origin-when-cross-origin">
<title>{escape(title)} · Pyk</title>
<link rel="canonical" href="{BASE}{paths[page]}">
<link rel="alternate" hreflang="en" href="{BASE}{PATHS['en'][page]}">
<link rel="alternate" hreflang="pl" href="{BASE}{PATHS['pl'][page]}">
<link rel="alternate" hreflang="x-default" href="{BASE}{PATHS['en'][page]}">
<meta property="og:type" content="website">
<meta property="og:title" content="{escape(title)} · Pyk">
<meta property="og:description" content="{escape(desc)}">
<meta property="og:url" content="{BASE}{paths[page]}">
<meta property="og:image" content="{BASE}assets/icon.png">
<link rel="icon" href="assets/icon.png" type="image/png">
<link rel="stylesheet" href="style.css">
</head>
<body>
<a class="skip" href="#main">{t['skip']}</a>
<header class="site-header wrap">
<a class="brand" href="{paths[0]}" aria-label="Pyk — {t['home']}"><img src="assets/icon.png" alt="" width="44" height="44"><span>Pyk<span class="brand-dot">.</span></span></a>
<nav class="main-nav" aria-label="{t['home']}">{nav}</nav>
<nav class="languages" aria-label="{t['language']}"><a href="{PATHS['en'][page]}" lang="en" hreflang="en" {'aria-current="true"' if lang == 'en' else ''}>EN</a><a href="{PATHS['pl'][page]}" lang="pl" hreflang="pl" {'aria-current="true"' if lang == 'pl' else ''}>PL</a></nav>
</header>
<main id="main">{content}</main>
<footer class="site-footer wrap"><div><a class="brand" href="{paths[0]}">Pyk<span class="brand-dot">.</span></a><p>{t['footer']}</p><small>© 2026 Oskar Śledź</small></div><nav aria-label="{t['rights']}"><a href="{paths[1]}">{t['privacy']}</a><a href="{paths[2]}">{t['delete']}</a><a href="mailto:hello@oskarsledz.pl">{t['contact']}</a></nav><span class="age-label">16+</span></footer>
</body>
</html>
'''

