def home(lang):
    h=HOME[lang]; p=PATHS[lang]
    steps=''.join(f'<article><span class="step-number">{n}</span><h3>{title}</h3><p>{body}</p></article>' for n,title,body in h['steps'])
    games=''.join(f'<article class="game-card {color}"><span class="game-symbol" aria-hidden="true">{symbol}</span><h3>{name}</h3><p>{body}</p></article>' for symbol,name,body,color in h['games'])
    faq=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in h['faq'])
    content=f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{h['tag']}</p><h1>{h['h1']}</h1><p class="lead">{h['intro']}</p><div class="actions"><a class="button primary" href="{STORE}">{h['download']} <span aria-hidden="true">↗</span></a><a class="text-link" href="#how">{h['how']} <span aria-hidden="true">↓</span></a></div><p class="meta">{h['note']}</p></div><div class="hero-art" role="img" aria-label="{h['demo']}"><div class="duel-label sticker">{h['duel']}</div><div class="play-card card-back"><span>✦</span><strong>{h['card3']}</strong></div><div class="play-card card-mid"><span>7 + 5</span><strong>{h['card1']}</strong></div><div class="play-card card-front"><img src="assets/icon.png" alt="" width="240" height="240"><strong>{h['card2']}</strong><div class="card-answer">♥</div></div><span class="round-sticker">{h['stamp']}</span><span class="art-spark" aria-hidden="true">✳</span><div class="match-label">{h['match']}</div></div></section>
<div class="ribbon"><div class="wrap">{''.join(f'<span>{x}</span>' for x in h['ribbon'])}</div></div>
<section class="section wrap" id="how"><p class="eyebrow">{h['eyebrow']}</p><h2>{h['heading']}</h2><div class="steps">{steps}</div></section>
<section class="games-section"><div class="section wrap"><div class="section-top"><div><p class="eyebrow">{h['gameslabel']}</p><h2>{h['gamesheading']}</h2></div><p class="lead">{h['gamesintro']}</p></div><div class="game-grid">{games}</div></div></section>
<section class="section wrap duo"><article class="solo-panel"><span class="eyebrow">{h['solo']}</span><h2>{h['soloh']}</h2><p>{h['solop']}</p><span class="bot-mark" aria-hidden="true">☺</span></article><article class="privacy-panel"><span class="privacy-mark" aria-hidden="true">↗</span><h2>{h['trust']}</h2><p>{h['trustp']}</p><a class="text-link" href="{p[1]}">{h['trustcta']} →</a></article></section>
<section class="section wrap faq"><h2>{h['faqtitle']}</h2><div>{faq}</div></section>
<section class="wrap final-cta"><div><h2>{h['ctah']}</h2><p>{h['ctap']}</p></div><a class="button primary" href="{STORE}">{h['download']} ↗</a></section>'''
    return layout(lang,0,h['title'],h['desc'],content)

# Legal text is rendered into HTML so it remains available without JavaScript.
SECTIONS = {
'en': [
('controller','Who is responsible', '''<p>The data controller is <strong>Oskar Śledź</strong>, the creator of Pyk, based in Poland. For privacy questions and requests, contact <a href="mailto:hello@oskarsledz.pl">hello@oskarsledz.pl</a>. This notice covers the Pyk mobile app and these public pages. Optional features process data only when they are available and you use them.</p>'''),
('data','Data, purposes & retention', '''<p>You provide profile and sign-in details, photos, feedback and game actions. We also receive game and usage records automatically, reports from other players and, if you choose them, sign-in or purchase information from service providers.</p><div class="table-wrap" role="region" aria-label="Data and retention" tabindex="0"><table><caption>What Pyk processes</caption><thead><tr><th scope="col">Data</th><th scope="col">Purpose</th><th scope="col">Retention</th></tr></thead><tbody>
<tr><td>Nickname, @handle, random account ID, chosen cosmetics and optional profile photo</td><td>Your profile, discovery, friends and rankings. Only the photo you choose is uploaded, not your gallery.</td><td>Until account deletion; a chosen photo can be removed earlier.</td></tr>
<tr><td>Optional email and password; Google account ID, email, name and photo if you sign in with Google</td><td>Sign-in, linking and account recovery. Passwords are hashed by Supabase Auth, not stored as plain text.</td><td>Until account deletion.</td></tr>
<tr><td>Rating, match counts, wins, coins, inventory, reward and referral records, Pyk+ status</td><td>Ranking, rewards, cosmetics and purchase entitlements.</td><td>Until account deletion.</td></tr>
<tr><td>Friends, invitations and latest online activity</td><td>Social play. Online status is visible to friends only.</td><td>Relationships until account deletion or removal; activity is refreshed about every 30 seconds and cleared when the app goes into the background.</td></tr>
<tr><td>Match participants, scores, results and confirmed duel outcomes</td><td>Fair ranking, disputes and a duel balance between current, unblocked friends.</td><td>Match records and duel outcomes: up to 12 months. Account deletion removes your participation and duel histories; a match record and another player's own participation may remain until ordinary expiry.</td></tr>
<tr><td>Random Bluetooth presence token linked to your account</td><td>Resolve a nearby token to a player profile.</td><td>The server mapping expires after 15 minutes unless refreshed. The app uses a new token when restarted; expiry of a mapping is not automatic token rotation.</td></tr>
<tr><td>Usage events, timestamps and account ID in Supabase</td><td>Measure use and improve the app. Event parameters exclude names, emails, invitation tokens and opponents' IDs.</td><td>90 days or earlier account deletion.</td></tr>
<tr><td>Firebase Analytics events, installation identifier, device and app details, approximate country derived from IP</td><td>Usage, retention and device statistics. Pyk does not set the Pyk account ID in Firebase or collect advertising IDs.</td><td>Under the project's Google Analytics retention settings. Detailed event/user data defaults to 2 months; aggregate reports may last longer. Contact us for the currently configured period.</td></tr>
<tr><td>Push device token and notification delivery records</td><td>Friend requests and game invitations. Notifications can include the sender's nickname.</td><td>Token until sign-out, account deletion or token expiry; server notification outbox: 7 days.</td></tr>
<tr><td>Product, store transaction ID, purchase/refund dates and Pyk+ expiry</td><td>Grant coins and subscription benefits, restore purchases and handle refunds. RevenueCat receives the account ID; Pyk does not send it your nickname or email.</td><td>Pyk records until account deletion. Store records follow Google/Apple's own legal retention. See deletion details below.</td></tr>
<tr><td>Optional feedback: description, category, optional email, platform, build and language</td><td>Handle bugs and ideas; reply if you provide an email. Sent through Web3Forms to our inbox, without a copy in Supabase and without automatically attaching account ID, logs or Bluetooth scans.</td><td>For handling the request and any necessary follow-up; provider and mailbox retention also applies. Request deletion by email.</td></tr>
<tr><td>Blocks, reports, moderation decisions: reporting/reported account, selected reason, optional shared match and time</td><td>Protect players and investigate abuse. Reports have no free-text field and are restricted to authorised moderators.</td><td>Until the related account is deleted or the relevant record is removed. There is no separate automatic expiry for these records in the current implementation.</td></tr>
<tr><td>Daily challenge attempts, scores, timing and reward records, when enabled</td><td>Limit attempts, validate scores and show a leaderboard of current, unblocked friends. Pending results are also stored locally for retry.</td><td>Account-linked server records until account deletion; pending local records are cleared on sign-out/deletion. No separate automatic history expiry is currently implemented.</td></tr>
<tr><td>Online queue ticket, supported game versions and queue/match times, when enabled</td><td>Pair compatible players, including people you do not know, and check queue quality; no GPS or Bluetooth data in tickets.</td><td>A waiting ticket expires after at most 120 seconds; ticket records are cleaned up after 180 days during queue entry or removed with the account.</td></tr>
<tr><td>Account-linked records of completed games and friend requests used for activation/retention statistics</td><td>Measure actual play and returning players, including after ordinary match records expire. Administrator reports are aggregate.</td><td>Until account deletion.</td></tr>
</tbody></table></div>'''),
('visibility','What other players can see', '''<p>Players who can view your profile can see your nickname, @handle, avatar or photo, rating, game statistics, cosmetics and Pyk+ badge. Nearby discovery and player search can expose this profile to people who are not your friends. Your email and sign-in details are not displayed to them.</p><p>Friend relationships are available to the two people involved. Online status and daily challenge standings are limited to current friends. Duel balance is available to the participants while they are current, unblocked friends. Your opponent receives the gameplay information needed for a match. Your block list and reports are not a public feed.</p>'''),
('permissions','Bluetooth & phone permissions', '''<p><strong>Bluetooth:</strong> a random 8-byte token is advertised, without your nickname, account ID or phone name. Nearby scans stay on your phone; the app asks the server to resolve Pyk tokens, rather than uploading a list of surrounding devices. The token is pseudonymous, not anonymous: the server can link an active token to your profile, and an observer can recognise the same token during a session.</p><p><strong>Location:</strong> Pyk does not collect GPS coordinates. Android 11 and earlier may require location permission for Bluetooth scanning; we do not use it to determine your position. Network providers and Firebase can process IP addresses, including to infer an approximate country.</p><p><strong>Camera:</strong> used to scan a friend's QR code; camera frames are processed on the phone and not uploaded. <strong>Photos:</strong> only a selected profile photo is uploaded. <strong>Notifications:</strong> managed through your phone settings. Denying a permission disables its related feature, rather than granting unrelated data access.</p><p>We do not access your contacts or phone number, show ads, sell personal data, or share it for cross-context behavioural advertising.</p>'''),
('basis','Why processing is permitted', '''<p>For users in the EEA/UK, our bases are: <strong>performance of the service contract</strong> (GDPR Article 6(1)(b)) for accounts, gameplay, friends, rewards and purchases; <strong>legitimate interests</strong> (Article 6(1)(f)) in security, fraud prevention, fair rankings, support and proportionate service statistics, subject to your rights; and <strong>legal obligations</strong> (Article 6(1)(c)) where records or disclosure are legally required. Where consent is required for non-essential device storage/access or analytics, that processing requires consent (Article 6(1)(a)); accepting this notice or an operating-system permission is not an analytics consent.</p><p>The current app sends usage events automatically when the online backend and Firebase are configured and does not offer a dedicated analytics consent switch. You may contact us to object or request deletion; an email request does not itself switch off collection on your device. This notice does not replace any consent controls required by local law.</p><p>Essential account and gameplay data are needed to provide online play. Email sign-in, profile photos, feedback and purchases are optional. We do not use automated decisions producing legal or similarly significant effects; game ratings, scores and queue pairing are calculated automatically to operate the games.</p>'''),
('providers','Service providers', '''<ul>
<li><a href="https://supabase.com/privacy">Supabase</a>: authentication, database, storage and real-time gameplay. The production project is in the EU West region, Ireland.</li>
<li><a href="https://firebase.google.com/support/privacy">Google / Firebase</a>: app analytics and Firebase Cloud Messaging when configured; Google also handles optional Google sign-in and Google Play purchases.</li>
<li><a href="https://www.apple.com/legal/privacy/">Apple</a>: APNs push delivery and App Store purchases where available.</li>
<li><a href="https://www.revenuecat.com/privacy/">RevenueCat</a>: purchase/subscription validation and entitlements when purchases are enabled.</li>
<li><a href="https://web3forms.com/privacy">Web3Forms</a> and our email provider: feedback delivery and support correspondence.</li>
<li><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Pages</a>: hosting this website, including connection/security data.</li></ul><p>Authorised administrators and moderators can access data needed for support, operations and safety. We may disclose data where legally required. App stores and sign-in providers also process information under their own terms; their independent records are not controlled by Pyk.</p>'''),
('international','Players around the world', '''<p>Pyk is distributed internationally. The main Supabase project is in Ireland, but this does not mean every provider stores or accesses all data only in the EU. Google, Apple, RevenueCat, Web3Forms, GitHub and their subprocessors may process data in other countries, including the United States. Their service-specific transfer terms and safeguards apply; contact us for information about the providers and safeguards relevant to your data.</p><p>Where applicable, international transfers must meet local legal requirements, including adequacy decisions or appropriate contractual safeguards. A privacy notice, or your use of Pyk, is not by itself a valid transfer mechanism and does not waive your local rights.</p><p><strong>EEA, UK and Switzerland:</strong> you may exercise applicable access, correction, deletion, restriction, portability and objection rights, withdraw consent where processing relies on consent, and complain to your local supervisory authority. In Poland this is <a href="https://uodo.gov.pl">UODO</a>.</p><p><strong>United States:</strong> where state privacy laws apply to Pyk, you may request access, correction, deletion or a copy of data, and appeal a refusal by contacting us with “Privacy appeal”. We do not sell data or share it for cross-context behavioural advertising. You will not be discriminated against for exercising applicable privacy rights; deleting essential data may prevent the service from working.</p><p><strong>Brazil:</strong> where the LGPD applies, you may request confirmation, access, correction, portability, information about recipients, and anonymisation, blocking or deletion of unnecessary or unlawfully processed data, or withdraw consent where applicable. You can also contact the <a href="https://www.gov.br/anpd/pt-br">ANPD</a>. See the Portuguese summary below.</p><p><strong>Other countries, including Canada, Australia and Japan:</strong> contact us for access, correction, deletion, consent questions or complaints under applicable local law. Mandatory local protections take precedence over any conflicting wording in this notice. Regional rights depend on the law's scope; availability in a country does not mean that every privacy statute applies to Pyk.</p>
<aside class="notice" lang="pt-BR"><h3>Resumo para pessoas no Brasil</h3><p>O controlador é Oskar Śledź, na Polônia. Contato: <a href="mailto:hello@oskarsledz.pl">hello@oskarsledz.pl</a>. Tratamos dados de perfil, partidas, amigos, uso do aplicativo e, quando utilizados, login, fotos, compras, notificações e denúncias, para prestar o serviço, garantir segurança e melhorar o Pyk. O projeto Supabase está na Irlanda. Prestadores como Google, Apple, RevenueCat, Web3Forms e GitHub podem tratar dados em outros países, inclusive nos Estados Unidos. Você pode solicitar informações sobre destinatários, países e garantias aplicáveis às transferências, além de confirmação, acesso, correção, portabilidade e eliminação, conforme a LGPD. É possível apresentar reclamação à ANPD. Este resumo não substitui as informações específicas e as garantias exigidas pela legislação brasileira.</p></aside>'''),
('rights','Your choices & requests', '''<p>Write to <a href="mailto:hello@oskarsledz.pl?subject=Pyk%20privacy%20request">hello@oskarsledz.pl</a> with your request and @handle. If your account is secured, use the linked email where possible. We may request proportionate proof that you control the account; never send us your password, one-time sign-in code or payment card details. An authorised representative may contact us where local law permits.</p><p>We respond within the time required by applicable law, normally within one month for GDPR requests; if a lawful extension is needed, we explain it. If we cannot fulfil a request, we explain why and the available complaint or appeal route. You can edit profile details in the app, remove a profile photo, manage permissions in phone settings, remove friends, block players and request account deletion.</p>'''),
('deletion','Deletion & remaining records', '''<p>Use <strong>Profile → Delete account</strong>, or follow our <a href="delete-account-en.html">account deletion instructions</a> without the app. This removes your authentication account, profile and account-linked server data, including friends, rewards, analytics events, push tokens, attempts, blocks/reports and duel histories. Photos are removed from Pyk storage as part of the app's deletion flow.</p><p>A match record and another participant's own data may remain until the 12-month limit. Pyk attempts to delete the RevenueCat subscriber through its server; this third-party step can fail independently and may need follow-up. Firebase events use a separate installation ID and are not automatically erased by deleting your Pyk account. Contact us about provider-held data; deletion depends on the identifiers available and the provider's process.</p><p>Feedback emails and providers' security, backup or legally required records are not automatically removed by the app action. Their applicable retention and deletion processes still apply. <strong>Deleting Pyk does not cancel an App Store or Google Play subscription</strong>; cancel it in the relevant store. Removing the app alone does not delete the server account.</p>'''),
('children','Age & young players', '''<p>Pyk is intended for people aged <strong>16 or older</strong>, or the higher minimum required by local law. It is not directed to children under 16, and does not offer a parental-consent flow or collect a date of birth for age verification. A store age/content rating does not override this rule. If local law requires a parent or guardian's involvement for a minor, that requirement still applies.</p><p>If you believe a child below the permitted age has provided personal data, contact us so we can investigate and delete it as appropriate. We do not knowingly collect data from children below the permitted age.</p>'''),
('website','Website, storage & security', '''<p>The public home, privacy and deletion pages do not embed analytics, advertising, external fonts or trackers, and do not set cookies or browser storage. GitHub Pages processes connection information such as IP addresses and request metadata under its own privacy statement. Following store or provider links takes you to their services.</p><p>The separate administrator panel uses Supabase authentication and browser storage for an administrator's session; it is not required to read these public pages. The mobile app stores account/session settings and pending daily results locally. We use encrypted network connections and server access controls; no system can guarantee absolute security.</p><p>This notice describes the features currently implemented. Server-controlled or optional features may be unavailable in a particular build. It does not imply that disabled social invitation links or private user-created challenges are active.</p>'''),
('changes','Changes to this notice', '''<p>The update date appears at the top of this page. We publish revisions here and communicate material changes through an appropriate available channel, such as an in-app announcement. Where a new purpose requires consent, an updated notice alone is not consent.</p>''')],
'pl': [
('controller','Kto odpowiada za dane', '''<p>Administratorem danych jest <strong>Oskar Śledź</strong>, twórca Pyk, działający w Polsce. Kontakt w sprawach prywatności i realizacji praw: <a href="mailto:hello@oskarsledz.pl">hello@oskarsledz.pl</a>. Polityka obejmuje aplikację mobilną Pyk i te publiczne strony. Funkcje opcjonalne przetwarzają dane wtedy, gdy są dostępne i z nich korzystasz.</p>'''),
('data','Dane, cele i czas przechowywania', '''<p>Dane profilu, logowania, zdjęcia, zgłoszenia i ruchy w grze podajesz sam. Automatycznie otrzymujemy też zapisy rozgrywek i użycia aplikacji, zgłoszenia od innych graczy oraz — przy wybraniu tych funkcji — dane logowania lub zakupów od dostawców usług.</p><div class="table-wrap" role="region" aria-label="Dane i retencja" tabindex="0"><table><caption>Jakie dane przetwarza Pyk</caption><thead><tr><th scope="col">Dane</th><th scope="col">Po co</th><th scope="col">Jak długo</th></tr></thead><tbody>
<tr><td>Nick, @nazwa, losowe ID konta, wybrane kosmetyki i opcjonalne zdjęcie profilowe</td><td>Profil, wykrywanie graczy, znajomi i ranking. Wysyłamy tylko wybrane zdjęcie, nie galerię.</td><td>Do usunięcia konta; wybrane zdjęcie możesz usunąć wcześniej.</td></tr>
<tr><td>Opcjonalny e-mail i hasło; ID Google, e-mail, imię i zdjęcie przy logowaniu Google</td><td>Logowanie, powiązanie i odzyskanie konta. Supabase Auth przechowuje skrót hasła, nie jego jawną treść.</td><td>Do usunięcia konta.</td></tr>
<tr><td>Rating, liczba gier i wygranych, monety, ekwipunek, zapisy nagród i poleceń, status Pyk+</td><td>Ranking, nagrody, kosmetyki i uprawnienia z zakupów.</td><td>Do usunięcia konta.</td></tr>
<tr><td>Znajomi, zaproszenia i ostatnia aktywność online</td><td>Wspólna gra. Status online widzą tylko znajomi.</td><td>Relacje do usunięcia konta lub relacji; aktywność jest odświeżana co ok. 30 s i czyszczona po przejściu aplikacji w tło.</td></tr>
<tr><td>Uczestnicy meczów, wyniki i potwierdzone rezultaty pojedynków</td><td>Uczciwy ranking, spory i bilans pojedynków między aktualnymi niezablokowanymi znajomymi.</td><td>Mecze i rezultaty pojedynków: do 12 miesięcy. Usunięcie konta usuwa Twój udział i historię par; rekord meczu i własny udział drugiego gracza mogą pozostać do zwykłego terminu usunięcia.</td></tr>
<tr><td>Losowy token Bluetooth powiązany z kontem</td><td>Rozpoznanie profilu gracza obok.</td><td>Powiązanie na serwerze wygasa po 15 minutach, jeśli nie jest odświeżane. Aplikacja tworzy nowy token po ponownym uruchomieniu; wygaśnięcie powiązania nie oznacza automatycznej rotacji tokenu.</td></tr>
<tr><td>Zdarzenia użycia, czas i ID konta w Supabase</td><td>Pomiar użycia i ulepszanie aplikacji. Parametry zdarzeń nie zawierają nicków, e-maili, tokenów zaproszeń ani ID rywali.</td><td>90 dni lub do wcześniejszego usunięcia konta.</td></tr>
<tr><td>Zdarzenia Firebase Analytics, identyfikator instalacji, informacje o urządzeniu i aplikacji, przybliżony kraj z IP</td><td>Statystyki użycia, powrotów i urządzeń. Pyk nie ustawia ID konta Pyk w Firebase i nie zbiera identyfikatorów reklamowych.</td><td>Według ustawień projektu Google Analytics. Domyślnie 2 miesiące dla danych szczegółowych zdarzeń/użytkowników; raporty zbiorcze mogą pozostać dłużej. O aktualny okres możesz zapytać mailowo.</td></tr>
<tr><td>Token urządzenia push i zapisy wysłanych powiadomień</td><td>Zaproszenia do znajomych i gry. Powiadomienie może zawierać nick nadawcy.</td><td>Token do wylogowania, usunięcia konta lub wygaśnięcia; kolejka wysłanych powiadomień na serwerze: 7 dni.</td></tr>
<tr><td>Produkt, ID transakcji sklepu, daty zakupu/zwrotu i koniec Pyk+</td><td>Nadanie monet i korzyści subskrypcji, przywracanie zakupów i zwroty. RevenueCat otrzymuje ID konta; Pyk nie wysyła mu nicku ani e-maila.</td><td>Zapisy Pyk do usunięcia konta. Sklepy zachowują własne dane zgodnie z ich obowiązkami prawnymi. Szczegóły usuwania poniżej.</td></tr>
<tr><td>Dobrowolne zgłoszenie: opis, kategoria, opcjonalny e-mail, platforma, build i język</td><td>Obsługa błędów i pomysłów; odpowiedź, jeśli podasz e-mail. Web3Forms dostarcza zgłoszenie do naszej skrzynki, bez kopii w Supabase i bez automatycznego dołączania ID konta, logów lub skanów Bluetooth.</td><td>Na czas obsługi i potrzebnych dalszych ustaleń; obowiązuje też retencja dostawcy i skrzynki. O usunięcie możesz poprosić mailowo.</td></tr>
<tr><td>Blokady, zgłoszenia i decyzje moderacji: konto zgłaszające/zgłoszone, wybrany powód, opcjonalny wspólny mecz i czas</td><td>Ochrona graczy i wyjaśnianie nadużyć. Zgłoszenia nie mają pola dowolnego tekstu; dostęp mają uprawnieni moderatorzy.</td><td>Do usunięcia powiązanego konta lub danego zapisu. Obecna implementacja nie ma osobnego automatycznego terminu wygasania tych danych.</td></tr>
<tr><td>Próby wyzwania dnia, wyniki, pomiary czasu i nagrody, gdy funkcja jest włączona</td><td>Limit prób, sprawdzanie wyników i tabela aktualnych niezablokowanych znajomych. Oczekujące wyniki są też zapisywane lokalnie do ponowienia wysyłki.</td><td>Zapisy serwerowe powiązane z kontem do jego usunięcia; oczekujące lokalne wyniki są czyszczone przy wylogowaniu/usunięciu. Nie ma osobnego automatycznego terminu wygasania historii.</td></tr>
<tr><td>Bilet kolejki online, obsługiwane wersje gier i czasy kolejki/meczu, gdy funkcja jest włączona</td><td>Dobranie zgodnych graczy, także nieznajomych, i sprawdzanie jakości kolejki; bez GPS i danych BLE.</td><td>Oczekiwanie wygasa najpóźniej po 120 s; zapisy biletów są sprzątane po 180 dniach przy wejściu do kolejki lub razem z kontem.</td></tr>
<tr><td>Zapisy ukończonych gier i próśb o znajomość powiązane z kontem, do statystyk aktywacji i powrotów</td><td>Pomiar rzeczywistej gry i powrotów, także po wygaśnięciu zwykłych rekordów meczów. Raporty administratora są zbiorcze.</td><td>Do usunięcia konta.</td></tr>
</tbody></table></div>'''),
('visibility','Co widzą inni gracze', '''<p>Gracz mający dostęp do profilu widzi nick, @nazwę, awatar lub zdjęcie, rating, statystyki gier, kosmetyki i znaczek Pyk+. Wykrywanie obok i wyszukiwanie graczy mogą udostępnić profil osobom spoza znajomych. Nie pokazujemy im e-maila ani danych logowania.</p><p>Relacja znajomości jest dostępna obu jej stronom. Status online i tabela wyzwania dnia są ograniczone do aktualnych znajomych. Bilans pojedynków widzą jego uczestnicy, gdy są aktualnymi niezablokowanymi znajomymi. Przeciwnik otrzymuje dane rozgrywki potrzebne do meczu. Lista blokad i zgłoszenia nie są publicznym kanałem.</p>'''),
('permissions','Bluetooth i uprawnienia telefonu', '''<p><strong>Bluetooth:</strong> telefon rozgłasza losowy 8-bajtowy token, bez nicku, ID konta i nazwy telefonu. Skany zostają na telefonie; aplikacja pyta serwer o tokeny Pyk zamiast wysyłać listę wszystkich urządzeń wokół. Token jest pseudonimowy, nie anonimowy: serwer może powiązać aktywny token z profilem, a obserwator rozpoznać ten sam token w trakcie sesji.</p><p><strong>Lokalizacja:</strong> Pyk nie zbiera współrzędnych GPS. Android 11 i starszy może wymagać zgody na lokalizację do skanowania Bluetooth; nie ustalamy na jej podstawie położenia. Dostawcy sieci i Firebase mogą przetwarzać adres IP, także do określenia przybliżonego kraju.</p><p><strong>Aparat:</strong> skanowanie QR znajomego; klatki obrazu są przetwarzane na telefonie i nie są wysyłane. <strong>Zdjęcia:</strong> wysyłamy tylko wybrane zdjęcie profilowe. <strong>Powiadomienia:</strong> zarządzasz nimi w ustawieniach telefonu. Odmowa uprawnienia wyłącza powiązaną funkcję, nie daje dostępu do innych danych.</p><p>Nie pobieramy kontaktów ani numeru telefonu, nie pokazujemy reklam, nie sprzedajemy danych i nie udostępniamy ich do reklamy behawioralnej między usługami.</p>'''),
('basis','Podstawy przetwarzania', '''<p>Dla użytkowników EOG/UK podstawami są: <strong>wykonanie umowy o usługę</strong> (art. 6 ust. 1 lit. b RODO) dla kont, gry, znajomych, nagród i zakupów; <strong>prawnie uzasadniony interes</strong> (lit. f) w bezpieczeństwie, ochronie przed oszustwami, uczciwym rankingu, wsparciu i proporcjonalnych statystykach usługi, z uwzględnieniem Twoich praw; <strong>obowiązek prawny</strong> (lit. c), gdy prawo wymaga przechowania lub ujawnienia danych. Jeśli niekonieczny zapis/odczyt danych urządzenia lub analityka wymagają zgody, potrzebna jest zgoda (lit. a); akceptacja polityki lub uprawnienia systemowego nie jest zgodą na analitykę.</p><p>Obecna aplikacja automatycznie wysyła zdarzenia użycia przy skonfigurowanym serwerze i Firebase, bez osobnego przełącznika zgody na analitykę. Możesz napisać ze sprzeciwem lub żądaniem usunięcia; e-mail sam nie wyłącza zbierania na Twoim urządzeniu. Ta polityka nie zastępuje mechanizmów zgody wymaganych lokalnym prawem.</p><p>Podstawowe dane konta i gry są niezbędne do gry online. Logowanie e-mailem, zdjęcia, zgłoszenia i zakupy są opcjonalne. Nie stosujemy automatycznych decyzji o skutkach prawnych lub podobnie istotnych; rating, wyniki i dobieranie kolejki są obliczane automatycznie w celu działania gier.</p>'''),
('providers','Dostawcy usług', '''<ul>
<li><a href="https://supabase.com/privacy">Supabase</a>: logowanie, baza, zdjęcia i rozgrywka w czasie rzeczywistym. Projekt produkcyjny jest w regionie EU West, Irlandia.</li>
<li><a href="https://firebase.google.com/support/privacy">Google / Firebase</a>: analityka i Firebase Cloud Messaging, gdy skonfigurowane; Google obsługuje też opcjonalne logowanie Google i zakupy Google Play.</li>
<li><a href="https://www.apple.com/legal/privacy/">Apple</a>: powiadomienia APNs i zakupy App Store, gdy dostępne.</li>
<li><a href="https://www.revenuecat.com/privacy/">RevenueCat</a>: weryfikacja zakupów/subskrypcji i uprawnienia, gdy zakupy są włączone.</li>
<li><a href="https://web3forms.com/privacy">Web3Forms</a> i dostawca naszej poczty: doręczenie zgłoszeń i korespondencja wsparcia.</li>
<li><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Pages</a>: hosting strony, w tym dane połączeń i bezpieczeństwa.</li></ul><p>Uprawnieni administratorzy i moderatorzy mają dostęp do danych potrzebnych do wsparcia, działania i bezpieczeństwa. Możemy ujawnić dane, gdy wymaga tego prawo. Sklepy i dostawcy logowania przetwarzają też dane na własnych zasadach; Pyk nie kontroluje ich niezależnych zapisów.</p>'''),
('international','Gracze na całym świecie', '''<p>Pyk jest dystrybuowany międzynarodowo. Główny projekt Supabase jest w Irlandii, ale nie oznacza to, że wszyscy dostawcy przechowują dane i mają do nich dostęp wyłącznie w UE. Google, Apple, RevenueCat, Web3Forms, GitHub i ich podwykonawcy mogą przetwarzać dane w innych krajach, także w USA. Obowiązują warunki i zabezpieczenia transferu dla danej usługi; napisz, aby uzyskać informacje o dostawcach i zabezpieczeniach dotyczących Twoich danych.</p><p>Gdy mają zastosowanie, transfery muszą spełniać lokalne wymagania prawne, w tym decyzje o odpowiednim poziomie ochrony lub właściwe zabezpieczenia umowne. Polityka ani korzystanie z Pyk same nie są ważną podstawą transferu i nie uchylają Twoich lokalnych praw.</p><p><strong>EOG, UK i Szwajcaria:</strong> możesz korzystać z właściwych praw dostępu, sprostowania, usunięcia, ograniczenia, przenoszenia i sprzeciwu, wycofać zgodę, gdy to ona jest podstawą, oraz złożyć skargę do lokalnego organu. W Polsce jest to <a href="https://uodo.gov.pl">UODO</a>.</p><p><strong>USA:</strong> gdy stanowe przepisy prywatności obejmują Pyk, możesz żądać dostępu, poprawienia, usunięcia lub kopii danych i odwołać się od odmowy, pisząc z tematem „Odwołanie w sprawie prywatności”. Nie sprzedajemy danych ani nie udostępniamy ich do reklamy behawioralnej między usługami. Nie dyskryminujemy za realizację właściwych praw; usunięcie niezbędnych danych może uniemożliwić działanie usługi.</p><p><strong>Brazylia:</strong> gdy obowiązuje LGPD, możesz żądać potwierdzenia, dostępu, poprawienia, przeniesienia, informacji o odbiorcach oraz anonimizacji, blokowania lub usunięcia zbędnych lub bezprawnie przetwarzanych danych i wycofać zgodę tam, gdzie jest podstawą. Możesz też zwrócić się do <a href="https://www.gov.br/anpd/pt-br">ANPD</a>. Poniżej znajduje się skrót po portugalsku.</p><p><strong>Inne kraje, w tym Kanada, Australia i Japonia:</strong> napisz w sprawie dostępu, sprostowania, usunięcia, zgody lub skargi na podstawie lokalnego prawa. Obowiązkowa lokalna ochrona ma pierwszeństwo przed sprzecznym zapisem tej polityki. Prawa regionalne zależą od zakresu ustawy; dostępność w kraju nie oznacza, że każda ustawa prywatności obejmuje Pyk.</p>
<aside class="notice" lang="pt-BR"><h3>Resumo para pessoas no Brasil</h3><p>O controlador é Oskar Śledź, na Polônia. Contato: <a href="mailto:hello@oskarsledz.pl">hello@oskarsledz.pl</a>. Tratamos dados de perfil, partidas, amigos, uso do aplicativo e, quando utilizados, login, fotos, compras, notificações e denúncias, para prestar o serviço, garantir segurança e melhorar o Pyk. O projeto Supabase está na Irlanda. Prestadores como Google, Apple, RevenueCat, Web3Forms e GitHub podem tratar dados em outros países, inclusive nos Estados Unidos. Você pode solicitar informações sobre destinatários, países e garantias aplicáveis às transferências, além de confirmação, acesso, correção, portabilidade e eliminação, conforme a LGPD. É possível apresentar reclamação à ANPD. Este resumo não substitui as informações específicas e as garantias exigidas pela legislação brasileira.</p></aside>'''),
('rights','Twoje wybory i żądania', '''<p>Napisz na <a href="mailto:hello@oskarsledz.pl?subject=Pyk%20-%20prywatnosc">hello@oskarsledz.pl</a>, podając żądanie i @nazwę. Jeśli konto jest zabezpieczone, w miarę możliwości użyj powiązanego e-maila. Możemy poprosić o proporcjonalne potwierdzenie kontroli nad kontem; nigdy nie wysyłaj hasła, jednorazowego kodu ani danych karty płatniczej. Upoważniony przedstawiciel może napisać, gdy dopuszcza to lokalne prawo.</p><p>Odpowiadamy w terminie wymaganym przez prawo, zwykle w ciągu miesiąca przy RODO; uzasadnimy dozwolone przedłużenie. W razie odmowy podamy powód i dostępną ścieżkę skargi lub odwołania. W aplikacji możesz edytować profil, usunąć zdjęcie, usunąć znajomych, blokować graczy i usunąć konto, a w ustawieniach telefonu zarządzać uprawnieniami.</p>'''),
('deletion','Usuwanie i pozostałe zapisy', '''<p>Wybierz <strong>Profil → Usuń konto</strong> lub skorzystaj z <a href="delete-account.html">instrukcji usuwania bez aplikacji</a>. Usuwa to konto logowania, profil i powiązane dane serwera: znajomych, nagrody, zdarzenia analityki, tokeny push, próby, blokady/zgłoszenia i historię pojedynków. Przepływ usuwania w aplikacji usuwa zdjęcia z magazynu Pyk.</p><p>Rekord meczu i własne dane innego uczestnika mogą pozostać do limitu 12 miesięcy. Pyk próbuje usunąć użytkownika RevenueCat przez serwer; ten etap może niezależnie się nie udać i wymagać ponowienia. Zdarzenia Firebase mają osobny identyfikator instalacji i usunięcie konta Pyk nie usuwa ich automatycznie. Napisz w sprawie danych dostawców; usuwanie zależy od dostępnych identyfikatorów i procedury dostawcy.</p><p>Wiadomości zgłoszeń i zapisy bezpieczeństwa, kopie lub dane wymagane prawem u dostawców nie znikają automatycznie po akcji w aplikacji. Nadal obowiązują właściwe okresy i procedury usuwania. <strong>Usunięcie konta Pyk nie anuluje subskrypcji App Store ani Google Play</strong>; anuluj ją w sklepie. Samo odinstalowanie aplikacji nie usuwa konta na serwerze.</p>'''),
('children','Wiek i młodsi gracze', '''<p>Pyk jest przeznaczony dla osób od <strong>16. roku życia</strong> lub wyższego wieku wymaganego lokalnym prawem. Nie jest kierowany do dzieci poniżej 16 lat; nie ma procesu zgody rodzica i nie zbiera daty urodzenia do weryfikacji wieku. Ocena wieku/treści w sklepie nie zmienia tej zasady. Jeśli prawo wymaga udziału rodzica lub opiekuna dla osoby niepełnoletniej, wymóg nadal obowiązuje.</p><p>Jeśli sądzisz, że dziecko poniżej dozwolonego wieku podało dane, napisz — sprawdzimy sprawę i odpowiednio je usuniemy. Nie zbieramy świadomie danych dzieci poniżej dozwolonego wieku.</p>'''),
('website','Strona, zapis lokalny i bezpieczeństwo', '''<p>Publiczne strony główna, prywatności i usuwania konta nie osadzają analityki, reklam, zewnętrznych fontów ani trackerów i nie ustawiają cookies lub pamięci przeglądarki. GitHub Pages przetwarza dane połączenia, np. adres IP i metadane żądania, zgodnie ze swoją polityką. Linki do sklepów i dostawców prowadzą do ich usług.</p><p>Osobny panel administratora używa logowania Supabase i pamięci przeglądarki do sesji administratora; nie jest potrzebny do czytania tych stron. Aplikacja zapisuje lokalnie ustawienia konta/sesji i oczekujące wyniki dnia. Używamy szyfrowanych połączeń i kontroli dostępu na serwerze; żaden system nie gwarantuje absolutnego bezpieczeństwa.</p><p>Opis dotyczy obecnie zaimplementowanych funkcji. Funkcje opcjonalne lub sterowane serwerem mogą być niedostępne w danym wydaniu. Polityka nie oznacza aktywowania wyłączonych linków społecznych lub prywatnych wyzwań tworzonych przez użytkowników.</p>'''),
('changes','Zmiany polityki', '''<p>Data aktualizacji jest na początku strony. Publikujemy tu nowe wersje i informujemy o istotnych zmianach odpowiednim dostępnym kanałem, np. ogłoszeniem w aplikacji. Jeśli nowy cel wymaga zgody, sama aktualizacja polityki nie jest zgodą.</p>''')]
}

def privacy(lang):
    t=LABELS[lang]
    title=t['privacy']
    intro={'en':'Your game. Your data. Clear rules. Here is what Pyk processes, who can see it and how you stay in control.', 'pl':'Twoja gra. Twoje dane. Jasne zasady. Sprawdź, co przetwarza Pyk, kto to widzi i jak zachowujesz kontrolę.'}[lang]
    links=''.join(f'<a href="#{sid}">{n:02} / {heading}</a>' for n,(sid,heading,body) in enumerate(SECTIONS[lang],1))
    sections=''.join(f'<section id="{sid}"><h2><span class="section-index">{n:02}</span>{heading}</h2>{body}</section>' for n,(sid,heading,body) in enumerate(SECTIONS[lang],1))
    content=f'''<div class="wrap legal-head"><a class="text-link" href="{PATHS[lang][0]}">← {t['back']}</a><p class="eyebrow">{t['rights']}</p><h1>{title}<span class="brand-dot">.</span></h1><p class="lead">{intro}</p><p class="meta">{t['updated']}</p></div><div class="wrap legal-layout"><aside class="toc"><nav aria-label="{t['toc']}"><strong>{t['toc']}</strong>{links}</nav></aside><article class="legal-body">{sections}<aside class="support-box"><h2>{t['support']}</h2><a class="button primary" href="mailto:hello@oskarsledz.pl">{t['email']} ↗</a></aside></article></div>'''
    return layout(lang,1,title,intro,content)

DELETE={
'en': {'title':'Delete your account', 'intro':'A clear way out, whenever you need it. Delete your Pyk account in the app or ask us by email.', 'inapp':'In the app', 'steps':['Open Pyk and go to <strong>Profile</strong>.','Choose <strong>Delete account</strong>.','Confirm the deletion. A completed request removes your account from the active service.'], 'warning':'Account deletion is permanent. Uninstalling the app does not delete your account.', 'without':'Without the app', 'emailbody':'Email <a href="mailto:hello@oskarsledz.pl?subject=Pyk%20account%20deletion">hello@oskarsledz.pl</a> with the subject <strong>“Pyk account deletion”</strong> and your <strong>@handle</strong>. If you secured your account with email or Google, write from that address where possible. If you have not secured it or have lost access, tell us; we will use a proportionate account-ownership check before deleting someone’s data.', 'emailnote':'We normally handle verified requests within 30 days, subject to applicable legal deadlines. We will tell you if more time is legally permitted and needed. Never send your password, sign-in code or card details.', 'request':'Request deletion by email', 'removed':'What is removed', 'removeitems':['Authentication account, nickname, @handle and Pyk profile photo.','Rating, your match participation, confirmed duel histories, friends and invitations.','Wallet, inventory, rewards, referrals and Pyk purchase records.','Bluetooth mappings, online status, push tokens and Supabase analytics events.','Account-linked daily attempts, queue tickets, activation records, blocks and reports.'], 'remain':'What may remain', 'remainbody':'A match record and another player’s own participation can remain until the 12-month retention limit; your participation row is removed. Firebase uses a separate installation ID, so deleting your Pyk account does not automatically erase Firebase history. Pyk attempts RevenueCat deletion; if that separate request fails, it may need follow-up. Feedback correspondence and providers’ backups, security or legally required records follow their own deletion and retention rules. Contact us about these records.', 'subscription':'Have a subscription?', 'subscriptionbody':'Deleting your Pyk account does not cancel recurring store billing. Cancel your subscription separately in the store where you purchased it. Account deletion does not automatically refund purchases.', 'more':'For the full data and retention details, read our', 'privacy':'privacy policy', 'google':'Manage Google Play subscriptions', 'apple':'Manage Apple subscriptions'},
'pl': {'title':'Usuń swoje konto', 'intro':'Jasna droga wyjścia, kiedy jej potrzebujesz. Usuń konto Pyk w aplikacji albo napisz do nas.', 'inapp':'W aplikacji', 'steps':['Otwórz Pyk i przejdź do <strong>Profilu</strong>.','Wybierz <strong>Usuń konto</strong>.','Potwierdź usunięcie. Zakończone żądanie usuwa konto z aktywnej usługi.'], 'warning':'Usunięcie konta jest trwałe. Samo odinstalowanie aplikacji nie usuwa konta.', 'without':'Bez aplikacji', 'emailbody':'Napisz na <a href="mailto:hello@oskarsledz.pl?subject=Usuniecie%20konta%20Pyk">hello@oskarsledz.pl</a> z tematem <strong>„Usunięcie konta Pyk”</strong> i podaj <strong>@nazwę</strong>. Jeśli konto jest zabezpieczone e-mailem lub Google, w miarę możliwości napisz z tego adresu. Jeśli nie jest zabezpieczone albo utraciłeś dostęp, wyjaśnij to — przed usunięciem danych zastosujemy proporcjonalne potwierdzenie kontroli nad kontem.', 'emailnote':'Zweryfikowane żądania obsługujemy zwykle w ciągu 30 dni, z uwzględnieniem terminów prawnych. Poinformujemy o potrzebnym przedłużeniu, gdy prawo je dopuszcza. Nigdy nie wysyłaj hasła, kodu logowania ani danych karty.', 'request':'Poproś o usunięcie mailowo', 'removed':'Co usuwamy', 'removeitems':['Konto logowania, nick, @nazwę i zdjęcie profilowe w Pyk.','Rating, Twój udział w meczach, historię potwierdzonych pojedynków, znajomych i zaproszenia.','Portfel, ekwipunek, nagrody, polecenia i zapisy zakupów Pyk.','Powiązania Bluetooth, status online, tokeny push i zdarzenia analityki Supabase.','Próby dnia, bilety kolejki, zapisy aktywacji, blokady i zgłoszenia powiązane z kontem.'], 'remain':'Co może pozostać', 'remainbody':'Rekord meczu i własny udział drugiego gracza mogą pozostać do limitu 12 miesięcy; wiersz Twojego udziału jest usuwany. Firebase używa osobnego identyfikatora instalacji, więc usunięcie konta Pyk nie usuwa automatycznie historii Firebase. Pyk próbuje usunąć dane RevenueCat; nieudane osobne żądanie może wymagać ponowienia. Korespondencja zgłoszeń oraz kopie, zapisy bezpieczeństwa i dane wymagane prawem u dostawców podlegają własnym zasadom usuwania i retencji. Napisz w sprawie tych zapisów.', 'subscription':'Masz subskrypcję?', 'subscriptionbody':'Usunięcie konta Pyk nie anuluje cyklicznych płatności sklepu. Anuluj subskrypcję osobno w sklepie, w którym ją kupiłeś. Usunięcie konta nie oznacza automatycznego zwrotu za zakupy.', 'more':'Pełny opis danych i czasu przechowywania znajdziesz w', 'privacy':'polityce prywatności', 'google':'Zarządzaj subskrypcjami Google Play', 'apple':'Zarządzaj subskrypcjami Apple'}
}

def deletion(lang):
    d=DELETE[lang]; t=LABELS[lang]
    steps=''.join(f'<li>{s}</li>' for s in d['steps'])
    items=''.join(f'<li>{s}</li>' for s in d['removeitems'])
    content=f'''<div class="wrap legal-head"><a class="text-link" href="{PATHS[lang][0]}">← {t['back']}</a><p class="eyebrow">{t['rights']}</p><h1>{d['title']}<span class="brand-dot">.</span></h1><p class="lead">{d['intro']}</p></div><div class="wrap deletion-grid"><section class="deletion-card"><span class="step-number">01</span><h2>{d['inapp']}</h2><ol class="delete-steps">{steps}</ol><p class="notice">{d['warning']}</p></section><section class="deletion-card"><span class="step-number pink">02</span><h2>{d['without']}</h2><p>{d['emailbody']}</p><p>{d['emailnote']}</p><a class="button primary" href="mailto:hello@oskarsledz.pl?subject=Pyk%20account%20deletion">{d['request']} ↗</a></section></div><article class="wrap deletion-details"><section><h2>{d['removed']}</h2><ul>{items}</ul></section><section><h2>{d['remain']}</h2><p>{d['remainbody']}</p></section><aside class="notice"><h2>{d['subscription']}</h2><p>{d['subscriptionbody']}</p><div class="store-links"><a href="https://play.google.com/store/account/subscriptions">{d['google']} ↗</a><a href="https://apps.apple.com/account/subscriptions">{d['apple']} ↗</a></div></aside><p>{d['more']} <a href="{PATHS[lang][1]}">{d['privacy']}</a>.</p></article>'''
    return layout(lang,2,d['title'],d['intro'],content)

for lang in ('en','pl'):
    for i,render in enumerate((home,privacy,deletion)):
        (ROOT / PATHS[lang][i]).write_text(render(lang),encoding='utf-8')
urls=''.join(f'<url><loc>{BASE}{p}</loc></url>' for paths in PATHS.values() for p in paths)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>\n',encoding='utf-8')
print('Built 6 public pages and sitemap.')
